<template><AdminLayout title="Messages"><div v-if="error" class="admin-error">{{error}}</div><div class="admin-card"><table class="table"><thead><tr><th>From</th><th>Subject</th><th>Message</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="m in messages" :key="m.id"><td><b>{{m.name}}</b><br>{{m.email}}<br>{{m.phone}}</td><td>{{m.subject}}</td><td>{{m.message}}</td><td><span class="badge">{{m.is_read?'Read':'New'}}</span></td><td><button v-if="!m.is_read" type="button" class="copy-btn" @click="read(m)">Mark read</button><a class="copy-btn" :href="`mailto:${m.email}?subject=Re: ${m.subject||'Won Nyaci Run'}`">Reply</a></td></tr></tbody></table></div></AdminLayout></template>
<script setup>import {ref,onMounted} from 'vue';import axios from 'axios';import AdminLayout from '../components/AdminLayout.vue';const messages=ref([]),error=ref('');const load=async()=>{try{messages.value=(await axios.get('/api/admin/messages')).data.data||[]}catch(e){error.value=e.response?.data?.message||'Could not load messages. Please sign in again.'}};const read=async m=>{try{await axios.post('/api/admin/messages/'+m.id+'/read');await load()}catch(e){error.value=e.response?.data?.message||'Could not mark this message as read.'}};onMounted(load)</script>
